import{d as c,C as t,o as u,c as b,j as a,a as o,E as n,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第三章","description":"从不尚贤、不贵货、不见可欲，辨认欲望竞争与无为之治的关系。","frontmatter":{"title":"道德经第三章","description":"从不尚贤、不贵货、不见可欲，辨认欲望竞争与无为之治的关系。","category":"guide","aliases":["道德经第三章","老子第三章","dao de jing chapter 3"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-03.md","filePath":"daoism/dao-de-jing/chapter-03.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-03.md"},y=c({...m,setup(x){const i=[{id:"honours-goods-and-desire",label:"不尚贤，使民不争",showLabel:!0,sentences:[["不",{text:"尚",glossary:"shang"},"贤，使民不争；"],["不",{text:"贵",glossary:"gui"},"难得之货，使民不为盗；"],["不",{text:"见",glossary:"xian"},"可欲，使民心不乱。"]],note:["【白话】不把贤能之名抬得过高，使百姓不竞相争夺；不把难得的财货看得过分贵重，使百姓不至于为它偷盗；不炫示足以引起贪欲的东西，使人心不被搅乱。","【王弼注择要】「贤犹能也」，又说「尚贤显名，荣过其任」。王弼区分任用能力与抬高名位，所批评的是荣名超过实际职任、贵货超过实际用途。","【读法】「见」读 xiàn，作显现、展示解。「不尚贤」不能简单译成不用贤能；但它确实在反省以名位驱动竞争的治理方式。"]},{id:"heart-belly-will-and-bones",label:"虚其心，实其腹",showLabel:!0,sentences:[["是以圣人之治，虚其心，实其腹，"],["弱其志，强其骨。"]],note:["【白话】所以，圣人的治理，是让百姓的心少些机巧与欲求，让肚腹得到充实；削弱争逐的意向，增强身体的筋骨。","【王弼注择要】「心怀智而腹怀食」，又说「志生事以乱」。心、腹、志、骨构成对照：减少生事的机巧与争逐，充实维持生活的根本。","【读法】「弱其志」所针对的并非现代意义上一切志向。这段也不只是个人养生，它仍在说治理者怎样影响百姓的生活与心志。"]},{id:"knowledge-desire-and-governance",label:"为无为，则无不治",showLabel:!0,sentences:[["常使民",{text:"无知",glossary:"wuzhi"},{text:"无欲",glossary:"wuyu"},"。"],["使夫",{text:"知",glossary:"zhi"},"者不敢为也。"],["为",{text:"无为",glossary:"wuwei"},"，则无不治。"]],note:["【白话】常使百姓保持少机巧、少贪求的状态，使那些善用智巧的人不敢妄为。以无为的方式施行治理，就没有不能治理好的。","【王弼注择要】「守其真也。」「知者谓知为也。」注把无知无欲连到守真，把知者连到善于施为的人，重心在机巧造作。","【读法】这里的知与智巧相通，不能只按现代的信息知识来读；也不能因此消去「使民」所包含的治理权力。末句是本章提出的理想，不能当作适用于所有制度的效果保证。"]}],r=[{id:"shang",term:"尚",sense:1},{id:"gui",term:"贵",sense:1},{id:"xian",term:"见",sense:1,pinyin:"xiàn",context:"「不见可欲」中的见作显现、展示解，读 xiàn。"},{id:"wuzhi",term:"无知",sense:1},{id:"wuyu",term:"无欲",sense:1,context:"此章在使民守真的治理语境中使用，指少贪求，不是要求取消基本生活需要。"},{id:"zhi",term:"知",sense:1,pinyin:"zhì",context:"知者的知与智相通，指善于机巧施为，读 zhì。"},{id:"wuwei",term:"无为",sense:1,context:"与不炫名、不贵货相连，强调减少人为刺激与机巧干预。"}];return(g,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三章",tabindex:"-1"},[o("道德经第三章 "),a("a",{class:"header-anchor",href:"#道德经第三章","aria-label":'Permalink to "道德经第三章"'},"​")],-1)),n(s,{title:"先看争欲怎样被激起",summary:"第三章把第二章对标举一端的警惕，落到名位、财货与治理。先看什么使人争逐，再读虚心实腹、无知无欲；既辨认王弼对智巧的批评，也保留对治理权力的追问。",points:[{label:"先读",text:"不尚、不贵、不见，分别减少什么刺激？"},{label:"再辨",text:"虚心与实腹、弱志与强骨为何成对？"},{label:"后想",text:"如何区分减少造作与限制人的自主？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),n(l,{sections:i,glossary:r,tone:"ink",density:"comfortable","aria-label":"《道德经》第三章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"不尚贤，使民不争。",tone:"辨名",guide:"王弼以荣名超过实际职任解释争的来源。任用能力与制造人人争夺的荣名，应先分开讨论。"},{text:"虚其心，实其腹，弱其志，强其骨。",tone:"辨本",guide:"这组对照把生活供养与争逐心志分开。若只讲减欲而忽略实腹强骨，就遗漏了本章对实际生活的要求。"},{text:"常使民无知无欲。",tone:"辨权",guide:"不能把无知直接读成反对一切学习，也不能只用保持纯真轻轻带过使民二字。它包含古代治理者对百姓状态的安排，须带着历史距离阅读。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=p("",15))])}}});export{_ as __pageData,y as default};
